/// <summary>
/// extension of formControl AVAButtonUpdatePurchaseOrder
/// </summary>
[ExtensionOf(formControlStr(PurchTable, AVAButtonUpdatePurchaseOrder))]
final class AVAPurchTableFrm_AVAButtonUpdatePurchaseOrder_Extension
{
}

Method.Source:
/// <summary>
/// AVA <c>clicked</c>
/// </summary>
public void clicked()
{
    next clicked();

    FormRun avaPurchTableFormRun = this.formRun();
    FormDataSource avaPurchTable_fds = avaPurchTableFormRun.dataSource(formDataSourceStr(PurchTable, PurchTable));
    str avaPurchOrders = element.avaGetDiffCategoryOrders(avaPurchTable_fds);

    if(avaPurchOrders == ''
        || (avaPurchOrders != ''
            && element.avaConfirmPurchTablesDialog(avaPurchOrders) == DialogButton::Yes))
    {
        element.avaButtonUpdatePurchaseOrderClicked();
    }
}
